    # Digits must be distinct and nonzero
    if d2 == d1 or d2 == d0 or d1 == d0 or d2 == 0 or d1 == 0 or d0 == 0:
        return False

    # m' = 10*d2 + d0
    m_prime = 10 * d2 + d0

    # Check divisibility constraint: m' | (10*d1 - 9*d0)
    target = 10 * d1 - 9 * d0

    if target == 0:
        # This is trivially divisible, but usually excluded in divisibility constraints unless specified. 
        # Since we are checking a structural constraint derived from m'|m, m'|0 holds.
        return True 

    if m_prime != 0 and target % m_prime == 0:
        return True
    return False

# Iterate over all possible distinct nonzero digits (1 to 9)
