from itertools import permutations

# --- Pre-defined Good Numbers (Based on available notes/problem statement) ---
# 1-digit good numbers
GOOD_SINGLE_DIGIT = {1, 2, 3, 4, 5, 6, 7, 8, 9}

# 2-digit good numbers (from notes.md)
GOOD_2_DIGIT = {
    12, 13, 14, 15, 16, 17, 18, 19, 21, 24, 25, 26, 28, 31, 32, 35, 36, 39, 41, 42, 45, 48, 51, 52, 61, 62, 63, 64, 65, 71, 72, 75, 81, 82, 84, 85, 91, 92, 93, 95, 96
}

# Cache for memoization
good_cache = {}

def get_digits(n):
    return [int(d) for d in str(n)]

def generate_subnumbers(n):
    """Generates all numbers formed by removing one digit from n."""
    s_n = str(n)
    subnumbers = set()
    for i in range(len(s_n)):
        sub = s_n[:i] + s_n[i+1:]
        if sub:
            subnumbers.add(int(sub))
    return list(subnumbers)

def is_good(m):
    """
    Checks if m is a good number. Uses memoization.
    """
    if m in good_cache:
        return good_cache[m]

    # 1. Single-digit case
    if m < 10:
        result = m in GOOD_SINGLE_DIGIT
        good_cache[m] = result
        return result

    # 2. Check derived numbers
    subnumbers = generate_subnumbers(m)

    for m_prime in subnumbers:
        # Check divisibility
        if m % m_prime == 0:
            # Check if the divisor m_prime is a good number
            if is_good(m_prime):
                # Found a condition for m being good
                good_cache[m] = True
                return True

    # If no condition is met
    good_cache[m] = False
    return False

def search_5_digit_good_numbers():
    # Digits available: 1 through 9
    digits = [1, 2, 3, 4, 5, 6, 7, 8, 9]

    # Generate all 5-digit numbers with distinct nonzero digits, sorted descendingly
    all_5_digit_candidates = sorted([
        int("".join(map(str, p))) for p in permutations(digits, 5)
    ], reverse=True)

    print("Starting search for 5-digit good numbers...")

    # Iterate through candidates in descending order
    for m in all_5_digit_candidates:
        if is_good(m):
            return m

    return -1 # Should not happen if the search space is correct

result = search_5_digit_good_numbers()
print(f"Largest 5-digit good number found: {result}")

